            //
            aOrbiterJ = ((aOrbiterJ + aOrbiterI) + 0x1115D182EE74D5C2ULL) + aNonceWordB;
            aOrbiterC = (aOrbiterC ^ aOrbiterJ) ^ 0x84A772AA3BC46FDBULL;
