            //
            aOrbiterC = ((aOrbiterC + aOrbiterB) + 0xEC938DD5DBF60492ULL) + aOrbiterUpdateSaltC[(((31U - aIndex) + 19U)) & S_SALT1];
            aOrbiterE = ((aOrbiterE ^ aOrbiterC) ^ 0x3EA2225C8A186678ULL) ^ aNonceWordG;
