            aCross = (RotL64(aPoisonLaneA[((S_BLOCK1 - aIndex + 11859U)) & S_BLOCK1], 5U) ^ RotL64(aPoisonLaneD[((S_BLOCK1 - aIndex + 10368U)) & S_BLOCK1], 47U));
