            aOrbiterF = (aOrbiterF + aOrbiterA) + 0x6F96BD6E7B2C684BULL;
            aOrbiterK = ((aOrbiterK ^ aOrbiterF) ^ 0x6C4441B8ABF4BBBEULL) ^ aOrbiterUpdateSaltB[(((31U - aIndex) + 9U)) & S_SALT1];
