            aWandererA = aWandererA + ((((RotL64(aPrevious, 51U) + aOrbiterH) + RotL64(aOrbiterK, 47U)) + RotL64(aCarry, 47U)) + aNonceWordB);
            aWandererC = aWandererC ^ ((RotL64(aCross, 21U) + aOrbiterI) + RotL64(aOrbiterA, 35U));
            aWandererH = aWandererH + (((RotL64(aScatter, 3U) + aOrbiterH) + RotL64(aOrbiterE, 19U)) + aNonceWordI);
            aWandererJ = aWandererJ ^ ((((RotL64(aPrevious, 60U) + RotL64(aOrbiterI, 41U)) + aOrbiterK) + aNonceWordM) + aPhaseBWandererUpdateSaltE[((aIndex + 11U)) & S_SALT1]);
            aWandererK = aWandererK + ((RotL64(aIngress, 35U) + RotL64(aOrbiterE, 57U)) + aOrbiterA);
