            aIngress = (RotL64(aFuseLaneC[((aIndex + 28551U)) & S_BLOCK1], 35U) ^ RotL64(aFuseLaneA[((aIndex + 28186U)) & S_BLOCK1], 51U));
            aIngress ^= RotL64(aSource[((S_BLOCK1 - aIndex + 28858U)) & S_BLOCK1], 12U);
            aIngress = TwistMix64::DiffuseA(((aIngress ^ aPhaseBDomainWordIngress) ^ aNonceWordF));
