            aCross = RotL64(aFuseLaneB[((S_BLOCK1 - aIndex + 31095U)) & S_BLOCK1], 34U) ^ RotL64(aFireLaneB[((S_BLOCK1 - aIndex + 27535U)) & S_BLOCK1], 5U);
            aCross = TwistMix64::DiffuseB(((aCross ^ aPhaseBDomainWordCross) ^ aNonceWordK));
