            aScatter = (RotL64(aCross, 52U) + RotL64(aIngress, 19U)) ^ (RotL64(aCarry, 37U) + RotL64(aPrevious, 5U));
            aScatter = TwistMix64::DiffuseA(((aScatter ^ aPhaseBDomainWordScatter) ^ aNonceWordB));
            //
            aOrbiterG = (aWandererD + RotL64(aScatter, 11U)) + 0x1C0670861EEE71DCULL;
            aOrbiterF = ((aWandererK + RotL64(aPrevious, 27U)) + 0x644CB6F8D3574FAFULL) + aNonceWordA;
