            aOrbiterC = ((aWandererG + RotL64(aCross, 21U)) + RotL64(aCarry, 37U)) + 0x92EBF8C0A8505DEEULL;
            aOrbiterK = ((aWandererH + RotL64(aIngress, 38U)) + 0xADA21A3B295B8BC4ULL) + aPhaseBOrbiterAssignSaltA[((aIndex + 15U)) & S_SALT1];
            aOrbiterB = ((aWandererF + RotL64(aScatter, 5U)) + 0xD46F4D7029642694ULL) + aPhaseBOrbiterAssignSaltF[(((31U - aIndex) + 6U)) & S_SALT1];
            aOrbiterA = (((aWandererJ + RotL64(aPrevious, 47U)) + RotL64(aCarry, 23U)) + 0x15530486B8AADCB0ULL) + aNonceWordL;
            //
            aOrbiterG = (((aOrbiterG + aOrbiterF) + 0xB826633993A2FEF5ULL) + aPhaseBOrbiterUpdateSaltB[(((31U - aIndex) + 9U)) & S_SALT1]) + aNonceWordE;
            aOrbiterI = ((aOrbiterI ^ aOrbiterG) ^ 0xCB3AF6F07AB7ECE4ULL) ^ aNonceWordG;
            aOrbiterI = RotL64((aOrbiterI * 0x7CD204520CBE5653ULL), 27U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterG) + 0xEBAB1232FB606769ULL;
            aOrbiterK = ((aOrbiterK ^ aOrbiterC) ^ 0x625C61D8ED014174ULL) ^ aPhaseBOrbiterUpdateSaltF[((aIndex + 20U)) & S_SALT1];
            aOrbiterK = RotL64((aOrbiterK * 0xDF90DCE5E63CE559ULL), 53U);
            //
            aOrbiterB = ((aOrbiterB + aOrbiterK) + 0x093C9EB70C81082BULL) + aNonceWordJ;
            aOrbiterF = (aOrbiterF ^ aOrbiterB) ^ 0x8626271483DD8BE4ULL;
            aOrbiterF = RotL64((aOrbiterF * 0x8826294123FA1A8DULL), 47U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterI) + 0x8E604D9C982C43A6ULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterK) ^ 0xBDD115B79CD305FAULL;
            aOrbiterA = RotL64((aOrbiterA * 0xA718392A3491CF57ULL), 35U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterC) + 0x66CACA566F3C6651ULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterI) ^ 0x0781E9397587E309ULL;
            aOrbiterB = RotL64((aOrbiterB * 0xE75BA943948294B1ULL), 13U);
            //
            aOrbiterF = ((aOrbiterF + aOrbiterA) + 0xC929FBE7626BAE41ULL) + aPhaseBOrbiterUpdateSaltC[(((31U - aIndex) + 11U)) & S_SALT1];
            aOrbiterC = (aOrbiterC ^ aOrbiterF) ^ 0xE025593CB769FDD1ULL;
            aOrbiterC = RotL64((aOrbiterC * 0xCC9BFAA8CE9BD06DULL), 41U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterB) + 0x62A990514819C7C3ULL;
            aOrbiterG = ((aOrbiterG ^ aOrbiterA) ^ 0x5D3B2D3A03A03C69ULL) ^ aPhaseBOrbiterUpdateSaltD[((aIndex + 16U)) & S_SALT1];
