            //
            aWandererF = aWandererF ^ ((RotL64(aScatter, 11U) + RotL64(aOrbiterB, 26U)) + aOrbiterF);
            aWandererK = aWandererK + (((RotL64(aCross, 35U) + RotL64(aOrbiterF, 13U)) + aOrbiterG) + RotL64(aCarry, 11U));
            aWandererD = aWandererD ^ ((RotL64(aPrevious, 57U) + RotL64(aOrbiterA, 57U)) + aOrbiterG);
            aWandererG = aWandererG + (((RotL64(aIngress, 29U) + RotL64(aOrbiterK, 47U)) + aOrbiterA) + RotL64(aCarry, 57U));
            aWandererA = aWandererA ^ ((RotL64(aPrevious, 42U) + RotL64(aOrbiterF, 19U)) + aOrbiterC);
            aWandererH = aWandererH + ((((RotL64(aScatter, 19U) + aOrbiterG) + RotL64(aOrbiterC, 5U)) + aNonceWordN) + aPhaseBWandererUpdateSaltA[((aIndex + 25U)) & S_SALT1]);
            aWandererJ = aWandererJ ^ ((((RotL64(aCross, 51U) + aOrbiterK) + RotL64(aOrbiterI, 41U)) + aNonceWordM) + aPhaseBWandererUpdateSaltE[((aIndex + 19U)) & S_SALT1]);
