    std::uint64_t aWandererK = *pWandererK;
    std::uint64_t aNonceWordA = TwistMix64::DiffuseA(pNonce * 0xA6EBD8FA63C7373FULL + 0xCC68BFF962094873ULL);
    std::uint64_t aNonceWordB = TwistMix64::DiffuseA(pNonce * 0xAF7B273E0DB45A51ULL + 0xEA8BA2E861A0D63EULL);
