            aCross = (RotL64(aIceLaneA[((S_BLOCK1 - aIndex + 23044U)) & S_BLOCK1], 43U) ^ RotL64(aHeartLaneB[((S_BLOCK1 - aIndex + 22475U)) & S_BLOCK1], 13U));
