            aCross = TwistMix64::DiffuseC(aCross);
            //
            aScatter = (RotL64(aCarry, 53U) + RotL64(aPrevious, 3U)) ^ (RotL64(aCross, 38U) ^ RotL64(aIngress, 21U));
            aScatter = TwistMix64::DiffuseA(aScatter);
            //
            aOrbiterA = (aWandererG + RotL64(aScatter, 13U)) + 0xA7A2253CF7BB209EULL;
            aOrbiterK = ((aWandererB + RotL64(aIngress, 43U)) + 0xD1430A569ECA3443ULL) + aPhaseCOrbiterAssignSaltC[((aIndex + 13U)) & S_SALT1];
            aOrbiterJ = (((aWandererA + RotL64(aCross, 37U)) + RotL64(aCarry, 3U)) + 0x29418C4417E845EEULL) + aPhaseCOrbiterAssignSaltE[((aIndex + 22U)) & S_SALT1];
            aOrbiterG = ((aWandererC + RotL64(aPrevious, 21U)) + RotL64(aCarry, 41U)) + 0x501146C8A508AD4AULL;
            aOrbiterE = (aWandererJ + RotL64(aScatter, 53U)) + 0xCB8284551E7D9083ULL;
            aOrbiterF = (aWandererD + RotL64(aPrevious, 28U)) + 0x8368894E710CA68FULL;
            aOrbiterH = ((aWandererE + RotL64(aIngress, 5U)) + RotL64(aCarry, 19U)) + 0x9C440E8607292F30ULL;
            //
            aOrbiterA = (aOrbiterA + aOrbiterK) + 0x33947D15E1665E0CULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterA) ^ 0x970D9739841951F5ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0xD169B1641708CCF1ULL), 13U);
