            //
            aOrbiterJ = (aOrbiterJ + aOrbiterF) + 0xCA6D92AA9F48A892ULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterJ) ^ 0x2BAD1FC6C507A4F4ULL;
            aOrbiterH = RotL64((aOrbiterH * 0x109D4890959DC92BULL), 19U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterA) + 0x17B1895D73C95E1BULL;
            aOrbiterK = ((aOrbiterK ^ aOrbiterE) ^ 0x668E9DD5C7254ACBULL) ^ aPhaseCOrbiterUpdateSaltB[(((31U - aIndex) + 28U)) & S_SALT1];
            aOrbiterK = RotL64((aOrbiterK * 0x5175B076C412F7B1ULL), 43U);
            //
            aOrbiterF = ((aOrbiterF + aOrbiterH) + 0x186C5083C2ED87EAULL) + aPhaseCOrbiterUpdateSaltD[((aIndex + 12U)) & S_SALT1];
            aOrbiterG = (aOrbiterG ^ aOrbiterF) ^ 0xE82BF369B2EC4CE7ULL;
            aOrbiterG = RotL64((aOrbiterG * 0x8238337B213E3EDBULL), 57U);
            //
            aOrbiterK = ((aOrbiterK + aOrbiterJ) + 0x289437F0CB5E1993ULL) + aPhaseCOrbiterUpdateSaltF[(((31U - aIndex) + 23U)) & S_SALT1];
            aOrbiterF = (aOrbiterF ^ aOrbiterK) ^ 0x8E396075645C63E3ULL;
            aOrbiterF = RotL64((aOrbiterF * 0x279A8DABAFC14D23ULL), 51U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterG) + 0x68DA3E556B1D6A77ULL;
            aOrbiterE = ((aOrbiterE ^ aOrbiterH) ^ 0xCF3A1A7F16B7F045ULL) ^ aPhaseCOrbiterUpdateSaltA[(((31U - aIndex) + 3U)) & S_SALT1];
            aOrbiterE = RotL64((aOrbiterE * 0x2C187DAB63C566AFULL), 27U);
            //
            aIngress = RotL64(aOrbiterE, 43U) ^ aOrbiterH;
            aIngress = aIngress + (RotL64(aOrbiterG, 28U) ^ aOrbiterF);
            aIngress = aIngress + (RotL64(aOrbiterJ, 3U) ^ aOrbiterK);
