            //
            aWandererE = aWandererE ^ (((RotL64(aIngress, 11U) + RotL64(aOrbiterA, 11U)) + aOrbiterJ) + aPhaseCWandererUpdateSaltD[((aIndex + 26U)) & S_SALT1]);
            aWandererB = aWandererB + (((RotL64(aCross, 41U) + aOrbiterK) + RotL64(aOrbiterJ, 41U)) + RotL64(aCarry, 57U));
            aWandererJ = aWandererJ ^ ((RotL64(aPrevious, 35U) + RotL64(aOrbiterG, 47U)) + aOrbiterH);
            aWandererA = aWandererA + ((RotL64(aScatter, 51U) + aOrbiterF) + RotL64(aOrbiterG, 23U));
            aWandererC = aWandererC ^ ((RotL64(aIngress, 57U) + RotL64(aOrbiterE, 57U)) + aOrbiterG);
