            aWandererD = aWandererD ^ (((RotL64(aScatter, 29U) + RotL64(aOrbiterJ, 3U)) + aOrbiterF) + aPhaseCWandererUpdateSaltC[(((31U - aIndex) + 14U)) & S_SALT1]);
            //
