            //
            aOrbiterF = (((aWandererI + RotL64(aIngress, 19U)) + RotL64(aCarry, 37U)) + 0x43952D6551AACD1FULL) + aPhaseBOrbiterAssignSaltF[(((31U - aIndex) + 7U)) & S_SALT1];
            aOrbiterG = ((aWandererG + RotL64(aCross, 35U)) + RotL64(aCarry, 53U)) + 0x8A175360B8D0843DULL;
            aOrbiterD = (aWandererE + RotL64(aScatter, 29U)) + 0x74CD4EC4D390A2E7ULL;
            aOrbiterK = ((aWandererC + RotL64(aPrevious, 53U)) + RotL64(aCarry, 11U)) + 0x1F26270C54DB3BCAULL;
            aOrbiterA = ((aWandererF + RotL64(aIngress, 3U)) + 0xC5F343A23A65E97EULL) + aPhaseBOrbiterAssignSaltD[(((31U - aIndex) + 24U)) & S_SALT1];
            aOrbiterI = (aWandererD + RotL64(aScatter, 10U)) + 0x18C2F41966EBB2CFULL;
            aOrbiterB = (aWandererA + RotL64(aPrevious, 41U)) + 0x53461EC8B64B5ABAULL;
