            //
            aOrbiterK = (aOrbiterK + aOrbiterA) + 0x4C9CD905490D3168ULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterK) ^ 0x8B31097F727F6AA4ULL;
            aOrbiterI = RotL64((aOrbiterI * 0xB76BCD79911F1395ULL), 29U);
            //
            aOrbiterA = ((aOrbiterA + aOrbiterI) + 0xABC993CE8E88960EULL) + aPhaseBOrbiterUpdateSaltB[(((31U - aIndex) + 14U)) & S_SALT1];
            aOrbiterB = (aOrbiterB ^ aOrbiterA) ^ 0x06C2B11F768FCD67ULL;
            aOrbiterB = RotL64((aOrbiterB * 0xC651D45B69EB1479ULL), 41U);
            //
            aOrbiterI = ((aOrbiterI + aOrbiterB) + 0x232AA617776E715FULL) + aPhaseBOrbiterUpdateSaltA[((aIndex + 16U)) & S_SALT1];
