            aOrbiterF = RotL64((aOrbiterF * 0x5441DDA8CF23CA53ULL), 51U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterK) + 0xE3D9B7641EF5F1C4ULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterD) ^ 0x0E49BAD67EE8F784ULL;
            aOrbiterA = RotL64((aOrbiterA * 0xDB9E1876745B25CDULL), 5U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterF) + 0xA7D7A580955B7812ULL;
            aOrbiterG = ((aOrbiterG ^ aOrbiterB) ^ 0x9CA06B3E2FEF51A0ULL) ^ aPhaseBOrbiterUpdateSaltD[(((31U - aIndex) + 9U)) & S_SALT1];
            aOrbiterG = RotL64((aOrbiterG * 0xECFB18B56754FC2DULL), 19U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterD) + 0x9F7DE98D9E1AA53CULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterG) ^ 0x4047905F311908FBULL;
